// apps/mobile/src/components/icons/FirstlineMark.tsx
//
// The Firstline mark. Web twin: apps/web/components/icons/FirstlineMark.tsx.
//
// The underlying PNG is a black-on-transparent mask generated by
// scripts/brand/generate_brand_assets.py, so it MUST be tinted — rendered
// untinted it is invisible against a dark background.
//
// Colour resolution deliberately uses useColorScheme() rather than useTheme():
// the loading and login screens mount before ThemeProvider does, and useTheme()
// throws outside the provider. Callers that do have theme context can pass
// `color` to override.

import React from 'react';
import { Image, useColorScheme, type ImageStyle, type StyleProp } from 'react-native';

import { brandColors } from '../../utils/colors';

interface FirstlineMarkProps {
  /** Rendered width and height in dp. */
  size?: number;
  /** Overrides the automatic light/dark tint. */
  color?: string;
  style?: StyleProp<ImageStyle>;
}

export const FirstlineMark: React.FC<FirstlineMarkProps> = ({
  size = 72,
  color,
  style,
}) => {
  const isDark = useColorScheme() === 'dark';
  const tintColor = color ?? (isDark ? brandColors.white : brandColors.black);

  return (
    <Image
      source={require('../../assets/firstline-mark.png')}
      style={[{ width: size, height: size, tintColor }, style]}
      resizeMode="contain"
      accessibilityRole="image"
      accessibilityLabel="Firstline"
    />
  );
};

export default FirstlineMark;
